#include "asm/field_script.inc"
#include "hoenn.h"
#include "hoenn_trainers.h"
#include "hoenn_story.inc"

    ScriptEntry DV2_TalkToPokemonScientist  // 1: RustboroCity_DevonCorp_2F_EventScript_TalkToPokemonScientist
    ScriptEntry DV2_BallScientist           // 2: RustboroCity_DevonCorp_2F_EventScript_BallScientist
    ScriptEntry DV2_PokenavScientist        // 3: RustboroCity_DevonCorp_2F_EventScript_PokenavScientist
    ScriptEntry DV2_PokemonDreamsScientist  // 4: RustboroCity_DevonCorp_2F_EventScript_PokemonDreamsScientist
    ScriptEntry DV2_FossilScientist         // 5: RustboroCity_DevonCorp_2F_EventScript_FossilScientist (Ch4)
    ScriptEntry DV2_Init                    // 6: RustboroCity_DevonCorp_2F_OnTransition (zone init)
    ScriptEntriesEnd
// ---- story

DV2_Init:                                   // OnTransition: a fossil left with the scientist is ready
    VMCall Sub_DV2_SetFossilReady
    VMHalt

Sub_DV2_SetFossilReady:                     // compare VAR_FOSSIL_RESURRECTION_STATE, 1 + call_if_eq SetFossilReady
    h_goto_if_ne VAR_FOSSIL_RESURRECTION_STATE, 1, L_DV2_Return
    h_setvar VAR_FOSSIL_RESURRECTION_STATE, 2
L_DV2_Return:
    VMReturn

DV2_TalkToPokemonScientist:
    h_lock
    SEPlay SEQ_SE_MESSAGE
    h_faceplayer
    VMCall Sub_DV2_SetFossilReady
    h_msgbox 0                              // We're developing a device for talking with Pokémon...
    h_release

DV2_BallScientist:
    h_lock
    SEPlay SEQ_SE_MESSAGE
    h_faceplayer
    VMCall Sub_DV2_SetFossilReady
    h_goto_if_set FLAG_MET_DEVON_EMPLOYEE, L_DV2_DevelopedBalls
    h_msgbox 1                              // I'm developing new kinds of Poké Balls...
    h_release
L_DV2_DevelopedBalls:
    h_msgbox 2                              // We finally made new kinds of Poké Balls!...
    h_release

DV2_PokenavScientist:
    h_lock
    SEPlay SEQ_SE_MESSAGE
    h_faceplayer
    VMCall Sub_DV2_SetFossilReady
    h_goto_if_set FLAG_RECEIVED_POKENAV, L_DV2_HasPokenav
    h_msgbox 3                              // I made the PokéNav!...
    h_release
L_DV2_HasPokenav:
    h_msgbox 4                              // Oh, wow! That's a PokéNav!...
    h_release

DV2_PokemonDreamsScientist:
    h_lock
    SEPlay SEQ_SE_MESSAGE
    h_faceplayer
    VMCall Sub_DV2_SetFossilReady
    h_msgbox 5                              // I'm trying to develop a device that visually reproduces the dreams...
    h_release

#include "scenes/RustboroCity_DevonCorp_2F_Fossil.inc"
    .balign 4, 0
